      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n만 18-30세 남녀) 온라인/모바일 게임 유저 대상 온라인 패널 모집\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.19. 19:18\n조회 51\n구독\n만 18-30세 남녀) 온라인/모바일 게임 유저 대상 온라인 패널 모집\n전국 거주/ 만 18-30세 남녀 게임커뮤니티 패널\n[모집대상]\n-만 18세~30세 남녀\n-온라인/모바일 비디오 게임을 즐겨하는 분으로, 다른 사람들과 같은팀/상대팀으로 함께 플레이하는 분\n-지난 2주내 프로 e스포츠경기 시청하신 분\n-유튜브, 넷플릭스, SNS등 다양한 온라인 활동을 하시는 분\n[참여혜택]\n커뮤니티 최종 가입 후 매월 2회 내외의 게임 관련 설문 참여 시 모바일 상품권 인센티브 지급\n(각 활동당 1만원~2만원상의 기프티콘 선택하여 수령: 해당 게임커뮤니티에서 수령. 종류:스벅쿠폰부터 네이버페이 포인트 등 다양함)\n[참여방법]\n보상 지급을 위한 필독 절차 (총 3단계)\n1. 아래 링크를 통해 참가 자격 확인 설문(약 5~10분) 완료\n2. 설문 합격자 대상으로 발송되는 '가입 안내 이메일' 확인\n3. 이메일 내 링크를 통해 커뮤니티 최종 회원가입 및 첫 로그인 완료\n※ 커뮤니티 가입 후 월 2회의 설문참여 시 사례쿠폰이 지급됩니다.\n▶▶ 1단계 설문 참여 링크:\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=d8fe3e74-46ce-4ab3-bad6-f36a8592ee98&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n****1단계 설문 참여 링크에서 소개자 이름은 필수로 입력해야 합니다. ****\n(필독!) ★ 설문 참여 시 주의사항 ★\n-설문 진행 중 창을 닫거나, 페이지 이탈하지 말아주세요.\n-설문 진행 중 복사&붙여넣기 하지 말아주세요.\n-설문 내에 불성실 응답 및 AI 자동 응답을 가려내기 위한 **[트랩 질문(한빛일보, 민성신문 등 존재하지 않는 신문사, 말루리아의 그림자 같은 존재하지 않는 게임등이 다수 포함되어 있습니다.\n-아무거나 빠르게 클릭하시면 자동 탈락하여 가입 메일이 발송되지 않으니, 반드시 지문을 꼼꼼히 읽고 답변해 주세요!\n-조건이 맞지 않으면 중간에 설문이 종료되거나 가입 메일이 가지 않을 수 있습니다.\n-주관식 문항에 아무 얘기나 작성하면 최종 가입 메일이 가지 않습니다. 꼼꼼히 작성해주세요.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n12/7~9) 만 20세~54세 남여) 24년 11월 이후 준중형 SUV 신차 구입하신 분 대상 조사\n좌담회알바좌담회카페\n26.11.19.\n댓글\n0\n만 18-30세 남녀) 온라인/모바일 게임 유저 대상 온라인 패널 모집\n좌담회알바좌담회카페\n26.11.19.\n댓글\n0\n11/30(월)~12/3 ★대규모★ 울쎄라/울쎄라피 프라임(리프팅) 경험자 좌담회 모집[40-65세 여성]\n좌담회알바좌담회카페\n26.11.19.\n댓글\n0\n만15~39세 남녀(중고등학생 포함) PC방에서 게임을 즐기는 분 대상 좌담회\n좌담회알바좌담회카페\n26.11.19.\n댓글\n0\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
